function revL(a,b){return document.documentElement.lang==='de'?b:a}
function revHub(){let L=revL;app.innerHTML='<button id=rvBack>'+L('رجع للرئيسية','Startseite')+'</button><section class=hero><span class=cap>SPEKTRUM A1</span><h1>'+L('فضاء المراجعة','Wiederholung')+'</h1><p>'+L('اختار الفصل. جاوب قبل ما تكشف النموذج، وعلّم على اللي بغيتي تعاود.','Wähle ein Kapitel. Erst antworten, dann vergleichen und Schwieriges markieren.')+'</p></section><div class=chaptergrid>'+COURSE.map((c,i)=>'<button data-rv="'+(i+1)+'"><strong>Kapitel '+(i+1)+'</strong><small>'+esc(c[0])+'</small></button>').join('')+'</div>';$('#rvBack').onclick=home;app.querySelectorAll('[data-rv]').forEach(b=>b.onclick=()=>revChapter(+b.dataset.rv));window.scrollTo(0,0)}
function revData(ch){let c=COURSE[ch-1],l=READER_LESSONS.find(x=>x.ch===ch),days=DAYS.filter(d=>d.c===ch),uniq=a=>[...new Map(a.map(x=>[x[0],x])).values()],m=readerModels[ch-1];
return [uniq(days.flatMap(d=>d.n)).map(([de,ar])=>[ar,de]),uniq([...l.phrases,...days.flatMap(d=>d.cards),...vocabExtras[ch-1].map(s=>s.split('|'))]).map(([de,ar])=>[ar,de]),c[2].map(([p,a,o,why])=>[p,a+' · '+why]),l.qs.map(([p,a])=>[p,a]),[[c[5],m[1]],[m[3]+' · '+revL('لعب الدورين بصوتك','Spiele beide Rollen'),m[4].split('|').join('\n')]]]}
function revChapter(ch){let L=revL,c=COURSE[ch-1],l=READER_LESSONS.find(x=>x.ch===ch),data=revData(ch),labels=[L('الأسماء والأدوات','Nomen und Artikel'),L('العبارات','Redemittel'),L('القواعد','Grammatik'),L('السمع والفهم','Hören und Verstehen'),L('الكتابة والحوار','Schreiben und Sprechen')],track=BOOK_AUDIO.find(x=>x.disc===l.track[0]&&x.n===l.track[1]),rs=readerStore(),key='rev3:'+ch,mem;try{mem=JSON.parse(rs.drafts[key])}catch{}mem??={marks:{},pos:{},notes:{}};const persist=()=>{rs.drafts[key]=JSON.stringify(mem);save()};const id=(k,i)=>k+':'+i;
function menu(){let weak=Object.keys(mem.marks).filter(x=>mem.marks[x]===1);app.innerHTML='<button id=rvBack>'+L('جميع الفصول','Alle Kapitel')+'</button><section class=hero><span class=cap>Kapitel '+ch+'</span><h2>'+esc(c[0])+'</h2><p>'+esc(c[1])+'</p></section>'+labels.map((t,k)=>'<button data-sec='+k+'>'+t+' <small dir=ltr>'+data[k].filter((_,i)=>mem.marks[id(k,i)]===2).length+' / '+data[k].length+'</small></button>').join('')+'<button class=gold id=rvWeak '+(!weak.length?'disabled':'')+'>'+L('عاود غير اللي صعاب عليك','Schwieriges wiederholen')+' ('+weak.length+')</button>';$('#rvBack').onclick=revHub;app.querySelectorAll('[data-sec]').forEach(b=>{let k=+b.dataset.sec;b.onclick=()=>run(data[k].map((_,i)=>[k,i]),k,mem.pos[k]||0)});$('#rvWeak').onclick=()=>run(weak.map(x=>x.split(':').map(Number)),'weak',0);window.scrollTo(0,0)}
function run(queue,sec,n){if(n>=queue.length)n=0;const [k,i]=queue[n],tag=id(k,i),[q,a]=data[k][i];app.innerHTML='<button id=rvBack>'+L('رجع لخريطة المراجعة','Kapitelübersicht')+'</button><section class=card><span class=cap>Kapitel '+ch+' · '+labels[k]+'</span><p dir=ltr>'+(n+1)+' / '+queue.length+'</p><progress max='+queue.length+' value='+n+'></progress>'+(k===3?'<p>'+L('سمع التسجيل وجاوب، ولا حل النص باش تقراه.','Höre zuerst zu oder lies den Text.')+'</p>'+(track?'<audio controls preload=none style="width:100%" src="'+esc(track.src)+'"></audio>':'')+'<details><summary>Text</summary><p dir=ltr style="white-space:pre-line">'+esc(l.text)+'</p></details>':'')+'<h3 dir=auto>'+esc(q)+'</h3>'+(k===4?'<textarea id=rvNote rows=5 lang=de dir=ltr placeholder="Schreib hier …"></textarea>':'')+'<button id=rvShow>'+L('كشف وقارن','Lösung vergleichen')+'</button><div id=rvAnswer hidden><p dir=auto style="white-space:pre-line">'+esc(a)+'</p><button id=rvYes>'+L('تذكّرتها','Gewusst')+'</button><button id=rvNo>'+L('باقي خاصني نعاودها','Noch üben')+'</button></div></section>';$('#rvBack').onclick=menu;if(sec===1){const b=document.createElement('button');b.textContent=L('قرا قصة فيها العبارات كاملة','Geschichte mit allen Redemitteln lesen');$('#rvBack').after(b);b.onclick=()=>showReiseStory(ch,data[1],()=>run(queue,sec,n))}$('#rvShow').onclick=e=>{e.target.hidden=true;$('#rvAnswer').hidden=false};if(k===4){$('#rvNote').value=mem.notes[tag]||'';$('#rvNote').oninput=e=>{mem.notes[tag]=e.target.value;persist()}}function mark(v){mem.marks[tag]=v;if(sec!=='weak')mem.pos[sec]=(n+1)%queue.length;persist();if(n+1<queue.length)run(queue,sec,n+1);else menu()}$('#rvYes').onclick=()=>mark(2);$('#rvNo').onclick=()=>mark(1);window.scrollTo(0,0)}menu()}
